import calendar
from datetime import date, timedelta

_WD_MAP = {
    "MO": 0,
    "TU": 1,
    "WE": 2,
    "TH": 3,
    "FR": 4,
    "SA": 5,
    "SU": 6,
}


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if freq == "DAILY":
        for i in range(count):
            result.append((start_date + timedelta(days=i * k)).isoformat())
        return result

    if freq == "WEEKLY":
        wds = sorted(_WD_MAP[code] for code in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        step = 0
        while len(result) < count:
            monday = week0_monday + timedelta(days=step * k * 7)
            for wd in wds:
                cand = monday + timedelta(days=wd)
                if cand >= start_date:
                    result.append(cand.isoformat())
                    if len(result) == count:
                        break
            step += 1
        return result

    if freq == "MONTHLY":
        base_months = start_date.year * 12 + (start_date.month - 1)
        step = 0
        if len(parts) == 3:
            target_day = int(parts[2])
            while len(result) < count:
                year, month0 = divmod(base_months + step * k, 12)
                month = month0 + 1
                days_in_month = calendar.monthrange(year, month)[1]
                day = days_in_month if target_day == -1 else target_day
                if 1 <= day <= days_in_month:
                    cand = date(year, month, day)
                    if cand >= start_date:
                        result.append(cand.isoformat())
                step += 1
        else:
            n = int(parts[2])
            wd = _WD_MAP[parts[3]]
            while len(result) < count:
                year, month0 = divmod(base_months + step * k, 12)
                month = month0 + 1
                first_wd, days_in_month = calendar.monthrange(year, month)
                if n == -1:
                    last_wd = (first_wd + days_in_month - 1) % 7
                    day = days_in_month - (last_wd - wd) % 7
                else:
                    day = 1 + (wd - first_wd) % 7 + (n - 1) * 7
                if 1 <= day <= days_in_month:
                    cand = date(year, month, day)
                    if cand >= start_date:
                        result.append(cand.isoformat())
                step += 1
        return result

    if freq == "YEARLY":
        mm, dd = map(int, parts[2].split("-"))
        step = 0
        while len(result) < count:
            year = start_date.year + step * k
            step += 1
            try:
                cand = date(year, mm, dd)
            except ValueError:
                continue
            if cand >= start_date:
                result.append(cand.isoformat())
        return result

    raise ValueError(f"Unsupported rule: {rule}")
